export type Expense = {
  id: string
  label: string
  amount: number
  currency: string
  status: string
}

export type NewExpense = { label: string; amount: number; currency: string }

export class ValidationError extends Error {
  errors: Record<string, string>
  constructor(errors: Record<string, string>) {
    super('Validation failed')
    this.errors = errors
  }
}

export async function fetchExpenses(signal?: AbortSignal): Promise<Expense[]> {
  const res = await fetch('/api/expenses', { signal })
  if (!res.ok) throw new Error(`Failed to load expenses (${res.status})`)
  return (await res.json()) as Expense[]
}

export async function createExpense(input: NewExpense): Promise<Expense> {
  const res = await fetch('/api/expenses', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(input),
  })
  if (res.status === 422) {
    const body = (await res.json().catch(() => null)) as {
      errors?: Record<string, string>
    } | null
    throw new ValidationError(body?.errors ?? {})
  }
  if (!res.ok) throw new Error(`Failed to submit expense (${res.status})`)
  return (await res.json()) as Expense
}
